-- 여행 상세 지도가 담긴 장소가 없을 때 목적지 지역 전체를 화면에 맞춰 보여 주도록 국내 여행지마다 지도 영역(위경도 사각형)을 둔다.
-- 출처: 국토교통부 공간정보 오픈플랫폼(V-World) 법정구역 읍면동 경계(LSMD_ADM_SECT_UMD, 2026-11 기준, EPSG:5186)
--   - 읍면동 경계를 시군구(COL_ADM_SE)별로 모아 WGS84로 변환한 뒤 최소·최대 위경도를 구했다. 시도 단위 여행지는 소속 시군구를 모두 합쳤다.
--   - 광주는 전남광주통합특별시 출범으로 단독 코드가 없어 통합 전 광주광역시 5개 구(12210, 12240, 12270, 12300, 12330)를 합쳤다.
--   - 먼 섬이 영역을 지나치게 넓히지 않게, 면적이 큰 읍면동 조각부터 전체 면적의 90%를 채우는 조각을 중심으로 잡고
--     그 영역에서 10km 안에 걸치는 조각만 포함했다(예: 울릉의 독도, 제주의 추자도 제외).
--   - 인천은 옹진군을 빼고 계산했다. 백령도가 큰 조각이라 위 규칙으로 걸러지지 않아 인천 영역이 서해 전체로 넓어지기 때문이다.
ALTER TABLE destination
    ADD COLUMN bounds_south DECIMAL(9, 6) NULL,
    ADD COLUMN bounds_west DECIMAL(9, 6) NULL,
    ADD COLUMN bounds_north DECIMAL(9, 6) NULL,
    ADD COLUMN bounds_east DECIMAL(9, 6) NULL;

CREATE TEMPORARY TABLE destination_bounds_seed
(
    name VARCHAR(50) NOT NULL PRIMARY KEY,
    south DECIMAL(9, 6) NOT NULL,
    west DECIMAL(9, 6) NOT NULL,
    north DECIMAL(9, 6) NOT NULL,
    east DECIMAL(9, 6) NOT NULL
);


UPDATE destination d
    JOIN destination_bounds_seed b ON b.name = d.name
SET d.bounds_south = b.south,
    d.bounds_west = b.west,
    d.bounds_north = b.north,
    d.bounds_east = b.east;

DROP TEMPORARY TABLE destination_bounds_seed;

-- 영역이 빠진 여행지가 있으면 여기서 마이그레이션이 실패한다.
ALTER TABLE destination
    MODIFY COLUMN bounds_south DECIMAL(9, 6) NOT NULL,
    MODIFY COLUMN bounds_west DECIMAL(9, 6) NOT NULL,
    MODIFY COLUMN bounds_north DECIMAL(9, 6) NOT NULL,
    MODIFY COLUMN bounds_east DECIMAL(9, 6) NOT NULL;

-- 여행은 국내 여행지 목록에서 고른 목적지를 반드시 참조한다. 지도 초기 위치와 기본 이름에만 쓰며 여행에 담을 장소의 지역을 제한하지 않는다.
-- 운영 데이터가 없어 목적지를 알 수 없는 기존 여행과 여행에 딸린 데이터는 지운다. 여행에 연결된 채팅방은 남긴다.
DELETE FROM expense_share;
DELETE FROM expense;
DELETE FROM trip_place;
DELETE FROM trip;

ALTER TABLE trip
    ADD COLUMN destination_id BIGINT NOT NULL AFTER room_id,
    ADD CONSTRAINT fk_trip_destination FOREIGN KEY (destination_id) REFERENCES destination (id);
